function tracking(){const params=new URLSearchParams(location.search),prefillId=params.get('commande')||'',prefillToken=params.get('token')||'';app.innerHTML=`<section class="page tracking-page"><div class="tracking-intro"><span class="eyebrow">Suivi commande</span><h1 class="page-title">Où en est ma commande ?</h1><p>Retrouvez l’avancement de votre commande avec les informations reçues lors de sa validation.</p><div class="tracking-values"><span><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="6" cy="17" r="2.2"></circle><circle cx="18" cy="7" r="2.2"></circle><path d="M8 16c2.4-.3 3.1-2 4-4s2.3-3.7 4-4"></path><path d="M4 6h5"></path><path d="m7 3 3 3-3 3"></path></svg> Circuit court</span><span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19.5 4.5C12 4.5 7.2 8.1 6.1 13.4c4.2.7 8.4-1.1 10.9-4.8-2 4.6-5.4 7.5-10.4 8.4"></path><path d="M6.6 17c-1.1.6-2 1.5-2.6 2.5"></path></svg> Produits locaux</span></div></div><form class="panel tracking-form" id="trackForm"><div class="custom-grid"><div class="field"><label>Numéro de commande</label><input name="id" required value="${escapeHtml(prefillId)}"></div><div class="field"><label>Jeton de suivi</label><input name="token" required value="${escapeHtml(prefillToken)}"></div></div><button class="btn">Afficher le suivi</button></form><div id="trackResult" aria-live="polite"></div></section>`;document.getElementById('trackForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),r=document.getElementById('trackResult');try{const o=await api('/api/orders/track',{method:'POST',body:JSON.stringify({id:f.get('id'),token:f.get('token')})}),steps=['Commande reçue','Commande acceptée','En préparation',o.fulfillment?.method==='Livraison à domicile'?'En livraison':'Prête au retrait','Livrée / récupérée'],current=o.status==='Annulée'?-1:Math.max(0,steps.indexOf(o.status));r.innerHTML=`<section class="panel tracking-card"><div class="tracking-head"><div><small>Commande</small><h2>${escapeHtml(o.id)}</h2></div><span class="status-pill">${escapeHtml(o.status)}</span></div>${o.status==='Annulée'?'<div class="notice">Cette commande a été annulée.</div>':`<div class="tracking-timeline">${steps.map((s,i)=>`<div class="tracking-step ${i<current?'done':i===current?'current':''}"><span>${i<current?'✓':i+1}</span><div><b>${escapeHtml(s)}</b>${i===current?'<small>Étape actuelle</small>':''}</div></div>`).join('')}</div>`}<div class="tracking-info"><div><small>Date prévue</small><b>${escapeHtml(o.fulfillment?.date||'')}</b></div><div><small>Créneau estimé</small><b>${escapeHtml(o.fulfillment?.slot||'')}</b></div><div><small>Total</small><b>${money(o.total)}</b></div></div></section>`}catch(err){r.innerHTML=`<div class="notice">${escapeHtml(err.message)}</div>`}};if(prefillId&&prefillToken)document.getElementById('trackForm').requestSubmit()}
function textBlocks(text){return escapeHtml(text||'').split(/\n{2,}/).filter(Boolean).map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('')}
function legalPage(type){const s=state.settings||{},gaActive=s.analyticsEnabled===true&&/^G-[A-Z0-9]+$/i.test(String(s.analyticsMeasurementId||'')),missing=[];if(!s.siret)missing.push('SIRET');if(!s.rneNumber)missing.push('RNE');if(!s.publicationDirector)missing.push('directeur de publication');if(!s.hostingAddress)missing.push('adresse de l’hébergeur');const mentions=s.legalNotice||`Éditeur du site\n${s.legalName||s.shopName||'LGY Boulangerie Pâtisserie'}${s.businessLegalForm?` — ${s.businessLegalForm}`:''}${s.businessCapital?` — Capital : ${s.businessCapital}`:''}\nAdresse : ${s.address||'À compléter'}\nTéléphone : ${s.phone||'À compléter'}\nE-mail : ${s.email||'À compléter'}\nSIRET : ${s.siret||'À compléter'}\nRNE : ${s.rneNumber||'À compléter'}${s.rcsNumber?`\nRCS : ${s.rcsNumber}`:''}${s.vatNumber?`\nTVA intracommunautaire : ${s.vatNumber}`:''}\n\nDirecteur de la publication\n${s.publicationDirector||'À compléter'}\n\nHébergement\n${s.hostingName||'À compléter'}\n${s.hostingAddress||'Adresse à compléter'}${s.hostingPhone?`\nTéléphone : ${s.hostingPhone}`:''}\n\nMédiation de la consommation\n${s.mediatorName||'Médiateur à désigner'}${s.mediatorAddress?`\n${s.mediatorAddress}`:''}${s.mediatorWebsite?`\n${s.mediatorWebsite}`:''}`;const privacy=s.privacyText||`Responsable du traitement\n${s.legalName||s.shopName||'LGY Boulangerie Pâtisserie'} — ${s.email||'contact à compléter'}.\n\nDonnées traitées\nLes données fournies lors de la création d’un compte ou d’une commande sont utilisées pour gérer la relation client, préparer et suivre les commandes, assurer le service après-vente et respecter les obligations comptables et légales.\n\nMesure d’audience\n${gaActive?`Avec votre consentement, le site utilise ${s.analyticsProvider||'Google Analytics 4'} (${s.analyticsMeasurementId}) afin de mesurer la fréquentation et l’utilisation générale du site. Le traceur n’est chargé qu’après acceptation. Le refus n’empêche pas l’utilisation du site. Les signaux publicitaires et la personnalisation publicitaire sont désactivés dans l’intégration LGY. La durée de conservation configurée à documenter dans Google Analytics est de ${Number(s.analyticsRetentionMonths||2)} mois.`:'Aucun identifiant Google Analytics valide n’est actuellement configuré : le traceur de mesure d’audience n’est donc pas chargé.'}\n\nVos choix\nVous pouvez accepter ou refuser la mesure d’audience depuis le bandeau, puis modifier votre choix à tout moment via « Gérer mes cookies » dans le pied de page.\n\nVos droits\nVous pouvez demander l’accès, la rectification, l’effacement ou la limitation de vos données et exercer les autres droits applicables en contactant ${s.email||'la boulangerie'}.`;const cookies=s.cookiesText||`Cookies et stockages strictement nécessaires\nLe site utilise des mécanismes techniques nécessaires au panier, à la sécurité, aux sessions de connexion et à la mémorisation de votre choix en matière de cookies. Ces éléments servent au fonctionnement demandé par l’utilisateur.\n\nMesure d’audience — Google Analytics 4\n${gaActive?`Identifiant configuré : ${s.analyticsMeasurementId}.\nFinalité : statistiques de fréquentation et amélioration du site.\nDéclenchement : uniquement après votre consentement.\nDurée du choix LGY : ${Number(s.analyticsConsentDays||180)} jours.\nConservation GA4 configurée à vérifier dans votre propriété : ${Number(s.analyticsRetentionMonths||2)} mois.\nPublicité : l’intégration LGY désactive les signaux et la personnalisation publicitaires.`:'Google Analytics est prévu dans le site mais reste inactif tant qu’un identifiant de mesure valide n’est pas renseigné dans l’administration.'}\n\nRefuser ou retirer son consentement\nLe bouton « Tout refuser » est proposé au même niveau que « Tout accepter ». Vous pouvez revenir sur votre choix à tout moment avec le bouton « Gérer mes cookies » présent en bas du site.`;const base={mentions:{eyebrow:'Informations légales',title:'Mentions légales',content:mentions},cgv:{eyebrow:'Vente en ligne',title:'Conditions générales de vente',content:s.termsText||`Les présentes conditions encadrent les commandes passées auprès de ${s.legalName||s.shopName||'LGY Boulangerie Pâtisserie'}.\n\nProduits et prix\nLes caractéristiques essentielles et les prix sont présentés dans la boutique avant validation. Les produits artisanaux peuvent présenter de légères variations d’aspect.\n\nCommande\nLe client vérifie son panier, ses coordonnées, le mode de retrait ou de livraison, la date et le créneau avant confirmation.\n\nPaiement\nLe mode de paiement disponible est indiqué avant la confirmation de commande.\n\nRetrait et livraison\n${s.deliveryTerms||'Les zones, frais, délais et créneaux configurés dans le site s’appliquent à la commande.'}\n\nProduits périssables et personnalisés\nLes règles relatives à l’annulation et au droit de rétractation doivent être adaptées à la nature des produits vendus et validées juridiquement avant ouverture.\n\nAnnulation et remboursement\n${s.refundTerms||'À compléter selon la politique commerciale de la boulangerie.'}\n\nMédiation\n${s.mediatorName?`En cas de litige non résolu, le consommateur peut saisir ${s.mediatorName}${s.mediatorWebsite?` — ${s.mediatorWebsite}`:''}.`:'Le médiateur de la consommation compétent doit être renseigné avant l’ouverture commerciale.'}`},privacy:{eyebrow:'Vos données',title:'Politique de confidentialité',content:privacy},cookies:{eyebrow:'Vie privée',title:'Cookies et mesure d’audience',content:cookies}}[type];app.innerHTML=`<section class="page legal-page"><span class="eyebrow">${base.eyebrow}</span><h1 class="page-title">${base.title}</h1>${type==='mentions'&&missing.length?`<div class="notice legal-warning"><b>À compléter avant ouverture :</b> ${escapeHtml(missing.join(', '))}.</div>`:''}<article class="panel legal-content">${textBlocks(base.content)}${type==='cgv'?`<hr><h2>Allergènes</h2><p>${escapeHtml(s.allergenNotice||'Pour toute allergie ou intolérance, contactez la boulangerie avant de commander.')}</p>`:''}${type==='cookies'?'<hr><button class="btn secondary" type="button" data-manage-cookies>Gérer mes cookies</button>':''}</article></section>`}
function notFound(){app.innerHTML='<section class="empty"><h1>Page introuvable</h1><p>Cette page n’existe pas ou n’est plus disponible.</p><a class="btn" href="/">Retour à l’accueil</a></section>'}
function route(){window.scrollTo(0,0);const clean=location.pathname.replace(/\/+$/,'')||'/',parts=clean.split('/').filter(Boolean),page=parts[0]||'',id=parts[1]||'';setActiveNav(page);const titles={'/':'LGY.fr — Boulangerie Pâtisserie','/boutique':'Notre boutique — LGY.fr','/panier':'Panier — LGY.fr','/commande':'Commande — LGY.fr','/admin':'Administration — LGY.fr','/suivi':'Suivi de commande — LGY.fr','/compte':'Mon compte — LGY.fr','/mentions-legales':'Mentions légales — LGY.fr','/cgv':'CGV — LGY.fr','/confidentialite':'Confidentialité — LGY.fr','/cookies':'Cookies — LGY.fr'};document.title=titles[clean]||(page==='produit'?`${state.products.find(p=>p.id===decodeURIComponent(id))?.name||'Produit'} — LGY.fr`:'LGY.fr');({'':home,'boutique':shop,'panier':cart,'commande':checkout,'admin':admin,'suivi':tracking,'compte':account,'mentions-legales':()=>legalPage('mentions'),'cgv':()=>legalPage('cgv'),'confidentialite':()=>legalPage('privacy'),'cookies':()=>legalPage('cookies')}[page]||(()=>page==='produit'?detail(id):page==='merci'?thanks(id):notFound()))();const nav=document.getElementById('mainNav');nav.classList.remove('open');document.getElementById('menuBtn').setAttribute('aria-expanded','false');setTimeout(()=>app.focus({preventScroll:true}),0);setTimeout(()=>trackPageView(),0)}
async function init(){if(location.hash.startsWith('#/'))history.replaceState({},'',location.hash.slice(1));document.getElementById('year').textContent=new Date().getFullYear();const menu=document.getElementById('menuBtn');menu.onclick=()=>{const nav=document.getElementById('mainNav'),open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))};document.addEventListener('click',e=>{if(e.target.closest('[data-consent-accept]')){saveConsent(true);return}if(e.target.closest('[data-consent-reject]')){saveConsent(false);return}if(e.target.closest('[data-consent-customize]')||e.target.closest('[data-manage-cookies]')){openConsentModal();return}if(e.target.closest('[data-consent-save]')){saveConsent(document.getElementById('analyticsConsentToggle').checked);return}if(e.target.closest('[data-consent-close]')||e.target.id==='cookieModalBackdrop'){closeConsentModal();return}if(e.target.closest('[data-cart-open]')){e.preventDefault();openCartDrawer();return}if(e.target.closest('[data-drawer-close]')||e.target.id==='cartDrawerBackdrop'){closeCartDrawer();return}const inc=e.target.closest('[data-drawer-inc]'),dec=e.target.closest('[data-drawer-dec]'),remove=e.target.closest('[data-drawer-remove]');if(inc||dec||remove){const key=inc?.dataset.drawerInc||dec?.dataset.drawerDec||remove?.dataset.drawerRemove,item=state.cart.find(x=>x.key===key);if(remove)state.cart=state.cart.filter(x=>x.key!==key);else if(item)item.qty=Math.max(1,Math.min(20,Number(item.qty)+(inc?1:-1)));saveCart();return}const a=e.target.closest('a[href^="/"]');if(a&&!a.hasAttribute('download')&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&a.target!=='_blank'){e.preventDefault();const u=new URL(a.href,location.origin);closeCartDrawer();navigate(u.pathname+u.search);return}if(!e.target.closest('.site-header')){document.getElementById('mainNav').classList.remove('open');menu.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCartDrawer()});updateCartCount();renderCartDrawer();try{[state.products,state.settings]=await Promise.all([api('/api/products'),api('/api/settings')]);await loadCustomerSession();route();initConsent()}catch{app.innerHTML='<div class="empty"><h2>Impossible de charger la boutique</h2><p>Vérifiez la connexion au serveur puis réessayez.</p></div>'}window.addEventListener('popstate',route);if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})}
init();
